318: vec3 F_Schlick_RoughnessDependent( const in vec3 F0, const in float dotNV, const in float roughness ) {
319: 	float fresnel = exp2( ( -5.55473 * dotNV - 6.98316 ) * dotNV );
320: 	vec3 Fr = max( vec3( 1.0 - roughness ), F0 ) - F0;
321: 	return Fr * fresnel + F0;
