323: float G_GGX_Smith( const in float alpha, const in float dotNL, const in float dotNV ) {
324: 	float a2 = pow2( alpha );
325: 	float gl = dotNL + sqrt( a2 + ( 1.0 - a2 ) * pow2( dotNL ) );
326: 	float gv = dotNV + sqrt( a2 + ( 1.0 - a2 ) * pow2( dotNV ) );
327: 	return 1.0 / ( gl * gv );
328: }
329: float G_GGX_SmithCorrelated( const in float alpha, const in float dotNL, const in float dotNV ) {
330: 	float a2 = pow2( alpha );
331: 	float gv = dotNL * sqrt( a2 + ( 1.0 - a2 ) * pow2( dotNV ) );
332: 	float gl = dotNV * sqrt( a2 + ( 1.0 - a2 ) * pow2( dotNL ) );
333: 	return 0.5 / max( gv + gl, EPSILON );
334: }
335: float D_GGX( const in float alpha, const in float dotNH ) {
336: 	float a2 = pow2( alpha );
337: 	float denom = pow2( dotNH ) * ( a2 - 1.0 ) + 1.0;
338: 	return RECIPROCAL_PI * a2 / pow2( denom );
339: }
340: vec3 BRDF_Specular_GGX( const in IncidentLight incidentLight, const in vec3 viewDir, const in vec3 normal, const in vec3 specularColor, const in float roughness ) {
341: 	float alpha = pow2( roughness );
342: 	vec3 halfDir = normalize( incidentLight.direction + viewDir );
343: 	float dotNL = saturate( dot( normal, incidentLight.direction ) );
344: 	float dotNV = saturate( dot( normal, viewDir ) );
345: 	float dotNH = saturate( dot( normal, halfDir ) );
346: 	float dotLH = saturate( dot( incidentLight.direction, halfDir ) );
347: 	vec3 F = F_Schlick( specularColor, dotLH );
348: 	float G = G_GGX_SmithCorrelated( alpha, dotNL, dotNV );
349: 	float D = D_GGX( alpha, dotNH );
350: 	return F * ( G * D );
351: }
352: vec2 LTC_Uv( const in vec3 N, const in vec3 V, const in float roughness ) {
