405: void BRDF_Specular_Multiscattering_Environment( const in GeometricContext geometry, const in vec3 specularColor, const in float roughness, inout vec3 singleScatter, inout vec3 multiScatter ) {
406: 	float dotNV = saturate( dot( geometry.normal, geometry.viewDir ) );
407: 	vec3 F = F_Schlick_RoughnessDependent( specularColor, dotNV, roughness );
408: 	vec2 brdf = integrateSpecularBRDF( dotNV, roughness );
409: 	vec3 FssEss = F * brdf.x + brdf.y;
410: 	float Ess = brdf.x + brdf.y;
411: 	float Ems = 1.0 - Ess;
412: 	vec3 Favg = specularColor + ( 1.0 - specularColor ) * 0.047619;	vec3 Fms = FssEss * Favg / ( 1.0 - Ems * Favg );
413: 	singleScatter += FssEss;
414: 	multiScatter += Fms * Ems;
415: }
