480: 			uv = vec2( - direction.x, - direction.z ) / abs( direction.y );
481: 		} else if ( face == 2.0 ) {
482: 			uv = vec2( - direction.x, direction.y ) / abs( direction.z );
483: 		} else if ( face == 3.0 ) {
484: 			uv = vec2( - direction.z, direction.y ) / abs( direction.x );
485: 		} else if ( face == 4.0 ) {
486: 			uv = vec2( - direction.x, direction.z ) / abs( direction.y );
487: 		} else {
