498: 		vec2 uv = getUV( direction, face ) * ( faceSize - 1.0 );
499: 		vec2 f = fract( uv );
500: 		uv += 0.5 - f;
501: 		if ( face > 2.0 ) {
502: 			uv.y += faceSize;
503: 			face -= 3.0;
504: 		}
505: 		uv.x += face * faceSize;
506: 		if ( mipInt < cubeUV_maxMipLevel ) {
507: 			uv.y += 2.0 * cubeUV_maxTileSize;
508: 		}
509: 		uv.y += filterInt * 2.0 * cubeUV_minTileSize;
510: 		uv.x += 3.0 * max( 0.0, cubeUV_maxTileSize - 2.0 * faceSize );
