512: 		vec3 tl = envMapTexelToLinear( texture2D( envMap, uv ) ).rgb;
513: 		uv.x += texelSize;
514: 		vec3 tr = envMapTexelToLinear( texture2D( envMap, uv ) ).rgb;
515: 		uv.y += texelSize;
516: 		vec3 br = envMapTexelToLinear( texture2D( envMap, uv ) ).rgb;
517: 		uv.x -= texelSize;
518: 		vec3 bl = envMapTexelToLinear( texture2D( envMap, uv ) ).rgb;
519: 		vec3 tm = mix( tl, tr, f.x );
520: 		vec3 bm = mix( bl, br, f.x );
521: 		return mix( tm, bm, f.y );
522: 	}
