181: 	return vec2( -1.04, 1.04 ) * a004 + r.zw;
182: }
183: float punctualLightIntensityToIrradianceFactor( const in float lightDistance, const in float cutoffDistance, const in float decayExponent ) {
184: #if defined ( PHYSICALLY_CORRECT_LIGHTS )
