186: 	if( cutoffDistance > 0.0 ) {
187: 		distanceFalloff *= pow2( saturate( 1.0 - pow4( lightDistance / cutoffDistance ) ) );
188: 	}
189: 	return distanceFalloff;
190: #else
191: 	if( cutoffDistance > 0.0 && decayExponent > 0.0 ) {
192: 		return pow( saturate( -lightDistance / cutoffDistance + 1.0 ), decayExponent );
193: 	}
194: 	return 1.0;
