251: vec3 LTC_EdgeVectorFormFactor( const in vec3 v1, const in vec3 v2 ) {
252: 	float x = dot( v1, v2 );
253: 	float y = abs( x );
254: 	float a = 0.8543985 + ( 0.4965155 + 0.0145206 * y ) * y;
255: 	float b = 3.4175940 + ( 4.1616724 + y ) * y;
256: 	float v = a / b;
257: 	float theta_sintheta = ( x > 0.0 ) ? v : 0.5 * inversesqrt( max( 1.0 - x * x, 1e-7 ) ) - v;
258: 	return cross( v1, v2 ) * theta_sintheta;
259: }
260: vec3 LTC_Evaluate( const in vec3 N, const in vec3 V, const in vec3 P, const in mat3 mInv, const in vec3 rectCoords[ 4 ] ) {
261: 	vec3 v1 = rectCoords[ 1 ] - rectCoords[ 0 ];
262: 	vec3 v2 = rectCoords[ 3 ] - rectCoords[ 0 ];
263: 	vec3 lightNormal = cross( v1, v2 );
264: 	if( dot( lightNormal, P - rectCoords[ 0 ] ) < 0.0 ) return vec3( 0.0 );
265: 	vec3 T1, T2;
266: 	T1 = normalize( V - N * dot( V, N ) );
267: 	T2 = - cross( N, T1 );
268: 	mat3 mat = mInv * transposeMat3( mat3( T1, T2, N ) );
269: 	vec3 coords[ 4 ];
270: 	coords[ 0 ] = mat * ( rectCoords[ 0 ] - P );
271: 	coords[ 1 ] = mat * ( rectCoords[ 1 ] - P );
272: 	coords[ 2 ] = mat * ( rectCoords[ 2 ] - P );
273: 	coords[ 3 ] = mat * ( rectCoords[ 3 ] - P );
274: 	coords[ 0 ] = normalize( coords[ 0 ] );
275: 	coords[ 1 ] = normalize( coords[ 1 ] );
276: 	coords[ 2 ] = normalize( coords[ 2 ] );
277: 	coords[ 3 ] = normalize( coords[ 3 ] );
278: 	vec3 vectorFormFactor = vec3( 0.0 );
279: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 0 ], coords[ 1 ] );
280: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 1 ], coords[ 2 ] );
281: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 2 ], coords[ 3 ] );
282: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 3 ], coords[ 0 ] );
283: 	float result = LTC_ClippedSphereFormFactor( vectorFormFactor );
284: 	return vec3( result );
285: }
