290: vec2 integrateSpecularBRDF( const in float dotNV, const in float roughness ) {
291: 	const vec4 c0 = vec4( - 1, - 0.0275, - 0.572, 0.022 );
292: 	const vec4 c1 = vec4( 1, 0.0425, 1.04, - 0.04 );
293: 	vec4 r = roughness * c0 + c1;
294: 	float a004 = min( r.x * r.x, exp2( - 9.28 * dotNV ) ) * r.x + r.y;
295: 	return vec2( -1.04, 1.04 ) * a004 + r.zw;
296: }
297: float punctualLightIntensityToIrradianceFactor( const in float lightDistance, const in float cutoffDistance, const in float decayExponent ) {
298: #if defined ( PHYSICALLY_CORRECT_LIGHTS )
299: 	float distanceFalloff = 1.0 / max( pow( lightDistance, decayExponent ), 0.01 );
300: 	if( cutoffDistance > 0.0 ) {
301: 		distanceFalloff *= pow2( saturate( 1.0 - pow4( lightDistance / cutoffDistance ) ) );
302: 	}
303: 	return distanceFalloff;
304: #else
305: 	if( cutoffDistance > 0.0 && decayExponent > 0.0 ) {
306: 		return pow( saturate( -lightDistance / cutoffDistance + 1.0 ), decayExponent );
307: 	}
308: 	return 1.0;
309: #endif
310: }
