361: float LTC_ClippedSphereFormFactor( const in vec3 f ) {
362: 	float l = length( f );
363: 	return max( ( l * l + f.z ) / ( l + 1.0 ), 0.0 );
364: }
365: vec3 LTC_EdgeVectorFormFactor( const in vec3 v1, const in vec3 v2 ) {
366: 	float x = dot( v1, v2 );
367: 	float y = abs( x );
368: 	float a = 0.8543985 + ( 0.4965155 + 0.0145206 * y ) * y;
369: 	float b = 3.4175940 + ( 4.1616724 + y ) * y;
370: 	float v = a / b;
371: 	float theta_sintheta = ( x > 0.0 ) ? v : 0.5 * inversesqrt( max( 1.0 - x * x, 1e-7 ) ) - v;
372: 	return cross( v1, v2 ) * theta_sintheta;
373: }
374: vec3 LTC_Evaluate( const in vec3 N, const in vec3 V, const in vec3 P, const in mat3 mInv, const in vec3 rectCoords[ 4 ] ) {
375: 	vec3 v1 = rectCoords[ 1 ] - rectCoords[ 0 ];
376: 	vec3 v2 = rectCoords[ 3 ] - rectCoords[ 0 ];
377: 	vec3 lightNormal = cross( v1, v2 );
378: 	if( dot( lightNormal, P - rectCoords[ 0 ] ) < 0.0 ) return vec3( 0.0 );
379: 	vec3 T1, T2;
380: 	T1 = normalize( V - N * dot( V, N ) );
381: 	T2 = - cross( N, T1 );
382: 	mat3 mat = mInv * transposeMat3( mat3( T1, T2, N ) );
383: 	vec3 coords[ 4 ];
384: 	coords[ 0 ] = mat * ( rectCoords[ 0 ] - P );
385: 	coords[ 1 ] = mat * ( rectCoords[ 1 ] - P );
386: 	coords[ 2 ] = mat * ( rectCoords[ 2 ] - P );
387: 	coords[ 3 ] = mat * ( rectCoords[ 3 ] - P );
388: 	coords[ 0 ] = normalize( coords[ 0 ] );
389: 	coords[ 1 ] = normalize( coords[ 1 ] );
390: 	coords[ 2 ] = normalize( coords[ 2 ] );
391: 	coords[ 3 ] = normalize( coords[ 3 ] );
392: 	vec3 vectorFormFactor = vec3( 0.0 );
393: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 0 ], coords[ 1 ] );
394: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 1 ], coords[ 2 ] );
395: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 2 ], coords[ 3 ] );
396: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 3 ], coords[ 0 ] );
397: 	float result = LTC_ClippedSphereFormFactor( vectorFormFactor );
398: 	return vec3( result );
399: }
400: vec3 BRDF_Specular_GGX_Environment( const in vec3 viewDir, const in vec3 normal, const in vec3 specularColor, const in float roughness ) {
401: 	float dotNV = saturate( dot( normal, viewDir ) );
402: 	vec2 brdf = integrateSpecularBRDF( dotNV, roughness );
403: 	return specularColor * brdf.x + brdf.y;
404: }
405: void BRDF_Specular_Multiscattering_Environment( const in GeometricContext geometry, const in vec3 specularColor, const in float roughness, inout vec3 singleScatter, inout vec3 multiScatter ) {
406: 	float dotNV = saturate( dot( geometry.normal, geometry.viewDir ) );
407: 	vec3 F = F_Schlick_RoughnessDependent( specularColor, dotNV, roughness );
408: 	vec2 brdf = integrateSpecularBRDF( dotNV, roughness );
409: 	vec3 FssEss = F * brdf.x + brdf.y;
410: 	float Ess = brdf.x + brdf.y;
411: 	float Ems = 1.0 - Ess;
412: 	vec3 Favg = specularColor + ( 1.0 - specularColor ) * 0.047619;	vec3 Fms = FssEss * Favg / ( 1.0 - Ems * Favg );
413: 	singleScatter += FssEss;
414: 	multiScatter += Fms * Ems;
415: }
